import{_ as r,l as i,o as t,c as s,v as o,p as l,x as e,d as u,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const X=JSON.parse('{"title":"quanto","description":"","frontmatter":{"title":"quanto","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/quanto-options.md","filePath":"quant/quanto-options.md","lastUpdated":1789023840000}'),m={name:"quant/quanto-options.md"};function _(p,a,q,B,E,c){const n=i("Mermaid");return t(),s("div",null,[a[1]||(a[1]=o('<h1 id="quanto" tabindex="-1">quanto <a class="header-anchor" href="#quanto" aria-label="Permalink to &quot;quanto&quot;">​</a></h1><div class="epigraph"><p>Quanto 用外国资产当标的、用本国货币固定数量结算；定价要把外汇与标的的协方差从漂移里减掉，而不是事后用即期汇率折算。</p><footer>—— Reiner, Quanto Mechanics, Risk, 1992</footer></div><p><a href="/quant/basket-rainbow">上一课</a>的多资产还在同一计价货币里。Quanto 的缺口是<strong>支付货币与标的货币脱钩</strong>：例如日经用美元按固定汇率结算，投资者不承担日元兑美元的兑换，却仍承担日经自己的风险。后课远期起始仍回到单货币；这里先把测度变换里的 quanto 调整写进漂移。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通外国股权期权：在外国测度下用外国利率定价，再把本金用随机 FX 换成本币——投资者同时暴露于股权与 FX。Quanto 把结算汇率钉死（或按预先约定的数量把外国支付换成本币），FX 路径不再进入支付，但<strong>定价核仍依赖 FX</strong>，因为本币测度下外国资产的漂移被协方差修正。漏掉这项，等于用外国 Black 公式再乘固定汇率，对相关的符号完全没暴露。</p><p>记外国资产 \\(S\\)（外币），汇率 \\(X\\)（外币的本币价格），Quanto 看涨支付 \\(X_0^{\\mathrm{fix}}\\bigl(S_T-K\\bigr)^+\\) 本币。风险中性（本币）下 \\(S\\) 的漂移不再是 \\(r_f-q\\)，而要减去 \\(\\rho\\sigma_S\\sigma_X\\)（约定随 \\(X\\) 定义而变号）。问题是把这条调整当成一等参数，而不是当「FX 台的事」。</p><h3 id="调整是测度-不是事后乘汇率" tabindex="-1">调整是测度，不是事后乘汇率 <a class="header-anchor" href="#调整是测度-不是事后乘汇率" aria-label="Permalink to &quot;调整是测度，不是事后乘汇率&quot;">​</a></h3><p>支付里没有随机 \\(X_T\\)，并不表示 \\(S\\) 的本币贴现价格自动是外国远期。本币计价的可交易资产是 \\(XS\\)（外国股票换成的本币价值）。Quanto 合约复制的是「外国期权、但用本币现金结算」，要对 \\(XS\\) 与 \\(X\\) 同时对冲，残差落在 \\(\\mathrm{d}S\\,\\mathrm{d}X\\) 的二次协变。Reiner 的 quanto mechanics 就是把这层协变收进 Black 的远期。</p><p><span class="marginnote">变号来自汇率报价惯例：USDJPY 与 EURUSD 哪个当 \\(X\\)，决定 \\(\\rho\\) 的经济含义。实现必须把「外币升值」与「\\(X\\) 上升」对齐，不能从彭博票据代码猜。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>GBM、常数相关：把外国远期换成 quanto 远期 \\(F^{\\mathrm{q}}=S_0 e^{(r_f-q-\\rho\\sigma_S\\sigma_X)T}\\)，再走 <a href="/quant/bsm">BSM</a>/Black。波动仍用外国资产自己的 \\(\\sigma_S\\)（在此模型下），不是本币资产 \\(XS\\) 的波动。有微笑时，外国香草曲面给出 \\(S\\) 的边际，FX 曲面给出 \\(X\\) 的边际，缺失的是 \\(S\\) 与 \\(X\\) 的相关微笑——市场很少直接报，通常用历史相关加压力，或从 quanto 产品自身反推。</p><p>对冲：Delta 对 \\(S\\)（在外国市场），Delta 对 \\(X\\)（quanto 调整项对 FX vol 与相关也敏感），以及外国期权的 Vega。不能只对冲本币指数期货，除非该期货本身就是 quanto。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>本币现金是计价。外国资产的本币价值 \\(XS\\) 在本币测度下以 \\(r\\) 增长（再扣股息）。Ito 展开 \\(\\mathrm{d}(XS)\\) 含 \\(\\rho\\) 项。Quanto 支付只含 \\(S\\)，相当于把 \\(X\\) 冻在常数上，复制时必须卖掉 \\(XS\\) 里 \\(X\\) 的那部分暴露，剩下 \\(S\\) 的漂移就被 \\(\\rho\\sigma_S\\sigma_X\\) 挪动。相关为正（资产涨时外币升值）时，quanto 看涨相对「外国期权×固定汇率」更便宜或更贵，取决于你如何定义 \\(X\\)；经济上是：结算不给你 FX 的顺风，定价核要事先扣掉。</p>',14)),(t(),l(d,null,{default:e(()=>[h(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20Foreign%5B%22%E5%A4%96%E5%9B%BD%E8%B5%84%E4%BA%A7%20S%22%5D%20--%3E%20Pay%5B%22Quanto%20%E6%94%AF%E4%BB%98%E9%92%89%E6%AD%BB%E7%BB%93%E7%AE%97%E6%B1%87%E7%8E%87%22%5D%0A%20%20FX%5B%22%E6%B1%87%E7%8E%87%20X%22%5D%20--%3E%20Cov%5B%22%E5%8D%8F%E6%96%B9%E5%B7%AE%20%CF%81%20%CF%83_S%20%CF%83_X%22%5D%0A%20%20Pay%20--%3E%20Drift%5B%22%E6%9C%AC%E5%B8%81%E6%B5%8B%E5%BA%A6%E4%B8%8B%20S%20%E7%9A%84%E6%BC%82%E7%A7%BB%E8%B0%83%E6%95%B4%22%5D%0A%20%20Cov%20--%3E%20Drift%0A%20%20Drift%20--%3E%20Black%5B%22%E4%BB%A3%E5%85%A5%20Black%20%E7%9A%84%20quanto%20%E8%BF%9C%E6%9C%9F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[u(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>常数相关、GBM 是教学闭式。股权微笑、FX 微笑、相关的期限结构都会让 quanto 调整变成一个曲面而不是一个数。分红、借券、外汇远期点差与 <a href="/quant/ndf">NDF</a> 市场都会进入 \\(F^{\\mathrm{q}}\\)。境内用人民币结算的境外标的、以及沪深港通下的结算安排，制度不同，不要把 Reiner 公式直接当 A 股 quanto。</p><p>本课不重写 <a href="/quant/fx-triangle">交叉汇率三角</a> 的无套利。Quanto 是衍生支付约定，不是即期交叉盘。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Quanto 结算货币与标的货币脱钩；支付无随机 FX，定价核仍有 \\(\\rho\\sigma_S\\sigma_X\\) 漂移调整。</li><li>闭式是把 Black 远期换成 quanto 远期；对冲仍要对 \\(S\\) 与 \\(X\\)。</li><li>相关的符号必须与汇率报价惯例对齐。</li><li>出处：Reiner, <em>Risk</em>, 1992。</li></ul>',5))])}const f=r(m,[["render",_]]);export{X as __pageData,f as default};
